{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")

    payload = case.get("payload")
    if payload is None:
        raise ValueError("Missing 'payload' field in case")

    if "segments" not in payload:
        raise ValueError("Missing 'segments' field in payload")
    if "budget" not in payload:
        raise ValueError("Missing 'budget' field in payload")

    segments = payload["segments"]
    budget = payload["budget"]

    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError("'segments' must be a non-empty list")
    if not isinstance(budget, (int, float)):
        raise ValueError("'budget' must be a number")

    for i, seg in enumerate(segments):
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in seg:
                raise ValueError(f"Segment {i} missing required field '{field}'")
        if seg["minimum"] < 0:
            raise ValueError(f"Segment {i} minimum must be non-negative")
        if seg["capacity"] < seg["minimum"]:
            raise ValueError(f"Segment {i} capacity must be >= minimum")

    names = [seg["name"] for seg in segments]
    importance = [seg["importance"] for seg in segments]
    minimums = [seg["minimum"] for seg in segments]
    capacities = [seg["capacity"] for seg in segments]

    quota_sum = sum(minimums)
    total_capacity = sum(capacities)

    if budget < quota_sum:
        raise ValueError(
            f"Budget {budget} is below the sum of minimum quotas {quota_sum}"
        )
    if budget > total_capacity:
        raise ValueError(
            f"Budget {budget} exceeds total capacity {total_capacity}"
        )

    alloc = list(minimums)
    remaining = budget - quota_sum

    while remaining > 0:
        best_idx = -1
        best_priority = None
        for i in range(len(segments)):
            if alloc[i] >= capacities[i]:
                continue
            priority = importance[i] / (alloc[i] + 1)
            if best_idx == -1 or priority > best_priority:
                best_priority = priority
                best_idx = i
        if best_idx == -1:
            raise ValueError("Cannot allocate remaining budget: all segments at capacity")
        alloc[best_idx] += 1
        remaining -= 1

    allocations = [
        {"name": names[i], "allocated": alloc[i]}
        for i in range(len(segments))
    ]
    name_mapping = {names[i]: alloc[i] for i in range(len(segments))}
    total = sum(alloc)

    return {
        "allocations": allocations,
        "name_mapping": name_mapping,
        "total": total
    }"}
